let interactive=document.querySelector(".interactive"),curX=0,curY=0,tgX=0,tgY=0,easeFactor=10;function move(){curX+=(tgX-curX)/easeFactor,curY+=(tgY-curY)/easeFactor,interactive.style.transform=`translate(${Math.round(curX)}px, ${Math.round(curY)}px)`,requestAnimationFrame(move)}window.addEventListener("pointermove",e=>{tgX=e.clientX,tgY=e.clientY}),move();